// Test support, compiled only in Debug builds (build.sh builds without DEBUG, so
// release apps never contain it). UI tests launch the app with
// OPENWARP_UITEST_SCENARIO set; the Store then talks to this in-process fake
// instead of the openwarp CLI, so UI tests need no daemon, network, root or
// Cloudflare account. Its JSON mirrors the CLI's `-j` output; the unit tests
// compare it with the contract fixtures generated by the Go tests.

import Foundation
import SwiftUI

#if DEBUG
enum UITestLaunch {
    static var scenario: FakeDaemon.Scenario? {
        ProcessInfo.processInfo.environment["OPENWARP_UITEST_SCENARIO"].flatMap(FakeDaemon.Scenario.init(rawValue:))
    }

    /// Models wired to one in-process fake daemon (with a fake installer and a
    /// fake Cloudflare trace), or nil for a normal launch.
    @MainActor static func models() -> AppModels? {
        guard let scenario else { return nil }
        Motion.forceReduced = true
        let fake = FakeDaemon(scenario: scenario)
        let defaults = UserDefaults(suiteName: "local.openwarp.uitest")!
        defaults.removePersistentDomain(forName: "local.openwarp.uitest")
        let newer = scenario == .updateAvailable ? "v9.9.0" : "v\(FakeDaemon.version)"
        return AppModels(store: Store(backend: fake),
                         setup: SetupModel(backend: fake, installer: FakeInstaller(daemon: fake)),
                         location: LocationModel(fetcher: FakeTrace(daemon: fake), defaults: defaults),
                         updates: UpdateChecker(fetcher: FakeReleases(tag: newer), defaults: defaults,
                                                currentVersion: FakeDaemon.version, build: nil))
    }
}

/// "Installs" the service: the fake daemon comes up, unless the scenario makes it fail.
struct FakeInstaller: ServiceInstaller {
    let daemon: FakeDaemon
    func install() async -> InstallResult {
        try? await Task.sleep(nanoseconds: 300_000_000)
        if daemon.scenario == .installFails { return .failed("launchctl bootstrap: 5: Input/output error") }
        await daemon.installService()
        return .installed
    }
}

/// GitHub's latest release, without the network.
struct FakeReleases: ReleaseFetcher {
    let tag: String
    func latest() async throws -> ReleaseInfo? {
        try? await Task.sleep(nanoseconds: 200_000_000)
        return ReleaseInfo(tag_name: tag, html_url: "https://github.com/ImanMontajabi/OpenWarp/releases/tag/\(tag)",
                           draft: false, prerelease: false)
    }
}

/// Cloudflare trace answers that follow the fake daemon's connection state.
struct FakeTrace: TraceFetcher {
    let daemon: FakeDaemon
    func trace(socks: String?) async throws -> String { await daemon.trace(socks: socks) }
}

actor FakeDaemon: Backend {
    enum Scenario: String {
        case registered, unregistered, connectFails = "connect-fails", daemonDown = "daemon-down"
        case installFails = "install-fails"   // daemon down, and installing fails
        case outdated                         // an older service is running
        case updateAvailable = "update-available"   // GitHub has a newer release
    }

    /// The version the fake daemon reports once "installed" (the app's own).
    static let version = "0.1.0"

    static let modeLabels: [String: String] = [
        "warp": "Traffic and DNS (UDP)", "warp+doh": "Traffic and DNS (HTTPS)", "warp+dot": "Traffic and DNS (TLS)",
        "doh": "DNS only (HTTPS)", "dot": "DNS only (TLS)", "proxy": "Local proxy (SOCKS5/HTTP)",
        "tunnel_only": "Traffic only",
    ]
    static let defaultExcludes = [
        "10.0.0.0/8", "100.64.0.0/10", "169.254.0.0/16", "172.16.0.0/12", "192.0.0.0/24",
        "192.168.0.0/16", "224.0.0.0/24", "240.0.0.0/4", "239.255.255.250/32", "255.255.255.255/32",
        "fe80::/10", "fd00::/8", "ff01::/16", "ff02::/16", "ff03::/16", "ff04::/16", "ff05::/16", "fc00::/7",
        "17.249.0.0/16", "17.252.0.0/16", "17.57.144.0/22", "17.188.128.0/18", "17.188.20.0/23",
        "2620:149:a44::/48", "2403:300:a42::/48", "2403:300:a51::/48", "2a01:b740:a42::/48",
    ]
    static let defaultFallback = [
        "corp", "domain", "home", "home.arpa", "host", "internal", "intranet", "invalid",
        "lan", "local", "localdomain", "localhost",
    ]
    /// Matches `openwarp -j settings` exactly, including `trusted_ssids: null` (a nil Go slice).
    static func defaultSettings() -> [String: Any] {
        ["mode": "warp", "protocol": "masque", "always_on": false, "families": "off", "proxy_port": 40000,
         "mtu": 1280, "split_mode": "exclude", "split_ips": defaultExcludes, "fallback_domains": defaultFallback,
         "trusted_ssids": NSNull(), "disable_wifi": false, "disable_ethernet": false, "post_quantum": true,
         "kill_switch": false]
    }

    let scenario: Scenario
    private(set) var calls: [[String]] = []
    private var settings = FakeDaemon.defaultSettings()
    private var registered: Bool
    private var license = "TEST0000-TEST0000-TEST0000"
    /// Disconnected, Connecting or Connected. Connecting lasts one status poll.
    private var conn = "Disconnected"
    private var reason: String?
    /// Whether the service is installed and running, and which version it runs.
    private var up: Bool
    private var runningVersion: String?
    /// Traffic of the current connection; grows on every status poll while connected.
    private var usageTx: UInt64 = 0, usageRx: UInt64 = 0
    private var usageSince = "2026-01-02T03:04:05Z"
    /// The last verification of the current connection (cleared when it reconnects).
    private var verification: [String: Any]?

    init(scenario: Scenario) {
        self.scenario = scenario
        registered = scenario != .unregistered
        up = scenario != .daemonDown && scenario != .installFails
        runningVersion = scenario == .outdated ? nil : Self.version
    }

    func installService() {
        up = true
        runningVersion = Self.version
    }

    func run(_ args: [String]) async -> (Data, String?) {
        calls.append(args)
        if args == ["service", "status"] { return ok(serviceStatus()) }   // works without the daemon
        if !up {
            return fail("cannot reach the openwarp daemon at /var/run/openwarp.sock (start it with `sudo openwarp daemon` or `openwarp service install`): connection refused")
        }
        switch args {
        case ["status"]: return ok(status())
        case ["settings"]: return ok(settings)
        case ["registration", "show"]:
            return registered ? ok(registration()) : fail("not registered: run `openwarp registration new`")
        case ["registration", "devices"]:
            return registered ? ok(Self.devices) : fail("not registered: run `openwarp registration new`")
        case ["registration", "new", "--accept-tos"]: registered = true; return ok(registration())
        case ["registration", "delete"]: registered = false; conn = "Disconnected"; return done()
        case ["connect"]:
            guard registered else { return fail("not registered: run `openwarp registration new`") }
            if conn == "Disconnected" { usageTx = 0; usageRx = 0; usageSince = "2026-01-02T03:04:\(10 + calls.count % 50)Z" }
            conn = "Connecting"; reason = nil; settings["always_on"] = true; verification = nil
            return done()
        case ["disconnect"]:
            conn = "Disconnected"; reason = "Manual Disconnection"; settings["always_on"] = false; verification = nil
            return done()
        case ["settings", "reset"]:
            let on = settings["always_on"], ks = settings["kill_switch"]
            settings = Self.defaultSettings(); settings["always_on"] = on; settings["kill_switch"] = ks
            return ok(settings)
        case ["killswitch", "on"], ["killswitch", "off"]: return patch("kill_switch", args[1] == "on")
        case ["verify"], ["verify", "--cloudflare"]: return verify(cloudflare: args.count == 2)
        case ["tunnel", "rotate-keys"]: return done()
        default: return setting(args)
        }
    }

    private func setting(_ a: [String]) -> (Data, String?) {
        switch (a.first, a.count) {
        case ("mode", 2):
            guard Self.modeLabels[a[1]] != nil else { return fail("invalid mode \"\(a[1])\"") }
            return patch("mode", a[1])
        case ("proxy", 3):
            guard let p = Int(a[2]), (1...65535).contains(p) else { return fail("usage: openwarp proxy port <1-65535>") }
            return patch("proxy_port", p)
        case ("registration", 3) where a[1] == "license":
            guard a[2].split(separator: "-").count == 3 else { return fail("Invalid license key") }
            license = a[2]
            return done()
        default: break
        }
        switch Array(a.prefix(3)) {
        case ["tunnel", "protocol", "set"] where a.count == 4: return patch("protocol", a[3].lowercased())
        case ["tunnel", "pq", "on"], ["tunnel", "pq", "off"]: return patch("post_quantum", a[2] == "on")
        case ["trusted", "wifi", "enable"], ["trusted", "wifi", "disable"]: return patch("disable_wifi", a[2] == "enable")
        case ["trusted", "ethernet", "enable"], ["trusted", "ethernet", "disable"]: return patch("disable_ethernet", a[2] == "enable")
        case ["dns", "families", "off"], ["dns", "families", "malware"], ["dns", "families", "full"]: return patch("families", a[2])
        case ["tunnel", "split-mode", "exclude"]: settings["split_ips"] = Self.defaultExcludes; return patch("split_mode", "exclude")
        case ["tunnel", "split-mode", "include"]: settings["split_ips"] = [String](); return patch("split_mode", "include")
        case ["tunnel", "endpoint", "reset"]: return patch("endpoint_override", "")
        case ["tunnel", "endpoint", "set"] where a.count == 4: return patch("endpoint_override", a[3])
        default: break
        }
        if a.count >= 3, let key = listKey(a) { return editList(key, Array(a.dropFirst(2))) }
        return fail("unknown command \"\(a.joined(separator: " "))\"")
    }

    private func listKey(_ a: [String]) -> String? {
        switch (a[0], a[1]) {
        case ("tunnel", "ip"): "split_ips"
        case ("dns", "fallback"): "fallback_domains"
        case ("trusted", "ssid"): "trusted_ssids"
        default: nil
        }
    }

    private func editList(_ key: String, _ a: [String]) -> (Data, String?) {
        var list = settings[key] as? [String] ?? []
        switch (a.first, a.count) {
        case ("add", 2): if !list.contains(a[1]) { list.append(a[1]) }
        case ("remove", 2): list.removeAll { $0 == a[1] }
        case ("reset", 1):
            switch key {
            case "split_ips": list = settings["split_mode"] as? String == "include" ? [] : Self.defaultExcludes
            case "fallback_domains": list = Self.defaultFallback
            default: list = []
            }
        default: return fail("unknown action")
        }
        return patch(key, list)
    }

    private func patch(_ key: String, _ value: Any) -> (Data, String?) {
        settings[key] = value
        if key == "mode" || key == "protocol", conn == "Connected" { conn = "Connecting"; verification = nil }
        return ok(settings)
    }

    private func status() -> [String: Any] {
        let mode = settings["mode"] as? String ?? "warp"
        var s: [String: Any] = [
            "status": conn, "mode": mode, "mode_label": Self.modeLabels[mode] ?? mode,
            "protocol": settings["protocol"] ?? "masque", "registered": registered, "warp_plus": false,
            "dns_protocol": mode.hasSuffix("doh") ? "doh" : mode.hasSuffix("dot") ? "dot" : "udp",
            "network": "Wi-Fi",
        ]
        if let runningVersion { s["version"] = runningVersion }
        if registered { s["account_type"] = "free" }
        if let reason { s["reason"] = reason }
        let shown = conn   // what this poll reports (a Connecting poll flips conn for the next one)
        switch conn {
        case "Connecting":
            if scenario == .connectFails {
                s["reason"] = "retrying in 4s"
                s["error"] = "dial 192.0.2.10:443: i/o timeout"
            } else {
                conn = "Connected"   // the next poll reports Connected
            }
        case "Connected":
            s["interface"] = mode == "proxy" ? nil : "utun9"
            s["interface_v4"] = "172.16.0.2"
            s["interface_v6"] = "2001:db8::2"
            if mode == "proxy" { s["proxy"] = "127.0.0.1:\(settings["proxy_port"] ?? 40000)" }
            s["tunnel"] = ["protocol": settings["protocol"] ?? "masque", "endpoint": "192.0.2.10:443",
                           "tx_bytes": 123456, "rx_bytes": 654321, "tx_packets": 100, "rx_packets": 200,
                           "handshake_rtt": "42ms", "tls": "TLS 1.3"] as [String: Any]
            s["dns"] = ["queries": 10, "fallback_queries": 2, "failures": 0]
            usageTx += 48_000; usageRx += 1_350_000   // roughly 32 KB/s up, 900 KB/s down at the app's 1.5 s poll
            s["usage"] = ["tx_bytes": usageTx, "rx_bytes": usageRx, "since": usageSince] as [String: Any]
        default: break
        }
        s["protection"] = protection(mode: mode, conn: shown)
        return s
    }

    /// Matches protection.go: the kill switch only applies to the tun modes with Exclude split tunnelling.
    private func protection(mode: String, conn: String) -> [String: Any] {
        let ksOn = settings["kill_switch"] as? Bool ?? false
        let applies = !["proxy", "doh", "dot"].contains(mode) && settings["split_mode"] as? String != "include"
        var p: [String: Any] = ["kill_switch": "off"]
        if ksOn && !applies {
            p["kill_switch"] = "unavailable"
            p["kill_switch_detail"] = mode == "proxy"
                ? "in Local proxy mode only apps that use the proxy are tunnelled; the system network is not changed"
                : "DNS-only modes do not tunnel traffic, so there is nothing to block it for"
        }
        switch conn {
        case "Connected":
            if ksOn && applies { p["kill_switch"] = "protecting" }
            p["state"] = (verification?["result"] as? String).map { $0 == "verified" ? "verified" : $0 == "failed" ? "failed" : "unverified" } ?? "unverified"
            if let verification { p["verification"] = verification }
            switch mode {
            case "proxy": p["ipv6"] = "proxy"; p["dns"] = "proxy"
            case "doh", "dot": p["dns"] = "encrypted"
            default:
                p["ipv6"] = "blocked"
                p["dns"] = mode == "warp" ? "tunnel" : mode == "tunnel_only" ? "system" : "encrypted"
            }
        case "Connecting":
            if ksOn && applies { p["kill_switch"] = "blocking"; p["kill_switch_detail"] = "no tunnel: traffic is blocked until the connection is back" }
            p["state"] = ksOn && applies ? "blocking" : "connecting"
        default:
            if ksOn && applies { p["kill_switch"] = "standby"; p["kill_switch_detail"] = "takes effect when you connect" }
            p["state"] = "unprotected"
        }
        return p
    }

    /// Matches `openwarp -j verify [--cloudflare]` for a healthy connection (documentation addresses).
    private func verify(cloudflare: Bool) -> (Data, String?) {
        guard conn == "Connected" else { return fail("not connected") }
        let mode = settings["mode"] as? String ?? "warp"
        let tun = !["proxy", "doh", "dot"].contains(mode)
        var checks: [[String: Any]] = [["name": "tunnel", "status": "pass", "detail": "masque via 192.0.2.10:443"]]
        if tun {
            checks.append(["name": "ipv4_route", "status": "pass", "detail": "IPv4 goes through utun9"])
            checks.append(["name": "ipv6_route", "status": "pass", "detail": "IPv6 is blocked (the tunnel has no IPv6 address)"])
        } else {
            checks.append(["name": "ipv4_route", "status": "skip", "detail": "Local proxy mode: only apps that use the proxy are tunnelled"])
        }
        checks.append(mode == "warp" ? ["name": "dns", "status": "pass", "detail": "system DNS: 1.1.1.1, 1.0.0.1"]
                                     : ["name": "dns", "status": "skip", "detail": "system DNS is not changed in this mode"])
        let ks = settings["kill_switch"] as? Bool ?? false
        checks.append(ks && tun ? ["name": "kill_switch", "status": "pass", "detail": "pf rules loaded and pf enabled"]
                                : ["name": "kill_switch", "status": "skip", "detail": "off"])
        if cloudflare {
            checks.append(["name": "cloudflare", "status": "pass", "detail": "Cloudflare reports warp=on (data centre FRA)"])
        }
        let result = tun || cloudflare ? "verified" : "incomplete"
        let v: [String: Any] = ["result": result, "at": "2026-01-02T03:04:05Z", "checks": checks]
        verification = v
        return ok(v)
    }

    /// Matches `openwarp -j service status`.
    private func serviceStatus() -> [String: Any] {
        var s: [String: Any] = ["installed": up, "loaded": up, "running": up, "app_version": Self.version,
                                "up_to_date": up && runningVersion == Self.version, "socket": "/var/run/openwarp.sock"]
        if up {
            s["program"] = runningVersion == Self.version ? "/Library/PrivilegedHelperTools/com.local.openwarp" : "/usr/local/bin/openwarp"
            if let runningVersion { s["version"] = runningVersion }
        } else {
            s["error"] = "cannot reach the openwarp daemon at /var/run/openwarp.sock: connection refused"
        }
        return s
    }

    /// What Cloudflare's trace would report on the current route (documentation addresses).
    func trace(socks: String?) -> String {
        let mode = settings["mode"] as? String ?? "warp"
        let viaWARP = socks != nil || (conn == "Connected" && mode != "proxy" && mode != "doh" && mode != "dot")
        return viaWARP ? "ip=198.51.100.7\ncolo=FRA\nloc=DE\nwarp=on\n" : "ip=203.0.113.10\ncolo=AMS\nloc=NL\nwarp=off\n"
    }

    private func registration() -> [String: Any] {
        ["id": "00000000-0000-4000-8000-000000000001", "account_id": "00000000-0000-4000-8000-000000000002",
         "account_type": "free", "warp_plus": false, "premium_data": 0, "quota": 0, "license": license,
         "public_key": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=", "key_type": "secp256r1",
         "interface_v4": "172.16.0.2", "interface_v6": "2001:db8::2", "created": "2026-01-02T03:04:05Z"]
    }

    static let devices: [[String: Any]] = [
        ["id": "00000000-0000-4000-8000-000000000001", "type": "macOS", "model": "Mac16,8", "name": "",
         "active": true, "role": "parent", "created": "2026-01-02T03:04:05Z", "activated": "2026-01-02T03:04:05Z"],
        ["id": "00000000-0000-4000-8000-000000000003", "type": "Android", "model": "PC", "name": "Old laptop",
         "active": false, "role": "child", "created": "2025-06-07T08:09:10Z", "activated": "2025-06-07T08:09:10Z"],
    ]

    private func ok(_ v: Any) -> (Data, String?) {
        ((try? JSONSerialization.data(withJSONObject: v, options: [.sortedKeys])) ?? Data(), nil)
    }
    private func done() -> (Data, String?) { ok(["ok": true]) }
    private func fail(_ msg: String) -> (Data, String?) { (Data(), msg) }
}
#endif
